                    // באמצע הזרימה; בלעדיו, נקודות המעבר האלו (סוף פרק) יוצאות
                    // "משוננות" בעוד שאר הטורים בספר חלקים.
                    {
                        const boundaryDiff = rCol.scrollHeight - lCol.scrollHeight;
